#include <iostream>
#include <vector>
#include <queue>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<bool> visited(n + 1, false);

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            vector<int> comp;
            queue<int> q;

            visited[i] = true;
            q.push(i);

            long long edges_sum = 0;

            while (!q.empty()) {
                int u = q.front();
                q.pop();
                comp.push_back(u);
                edges_sum += adj[u].size();

                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }

            long long v_c = comp.size();
            long long e_c = edges_sum / 2;

            if (e_c < v_c * (v_c - 1) / 2) {
                // A componente não é completa.
                // Encontra um vértice com grau < v_c - 1.
                int start_node = -1;
                for (int u : comp) {
                    if ((long long)adj[u].size() < v_c - 1) {
                        start_node = u;
                        break;
                    }
                }

                // BFS a partir de start_node para encontrar um vértice a distância 2.
                vector<int> dist(n + 1, -1);
                queue<int> bfs_q;

                dist[start_node] = 0;
                bfs_q.push(start_node);

                while (!bfs_q.empty()) {
                    int u = bfs_q.front();
                    bfs_q.pop();

                    if (dist[u] == 2) {
                        cout << start_node << " " << u << "\n";
                        return 0;
                    }

                    for (int v : adj[u]) {
                        if (dist[v] == -1) {
                            dist[v] = dist[u] + 1;
                            bfs_q.push(v);
                        }
                    }
                }
            }
        }
    }

    cout << -1 << "\n";
    return 0;
}
